WITH with_last AS (SELECT s.*, latest.employee_job_title FROM departments s LEFT JOIN LATERAL (SELECT c.job_title AS employee_job_title FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT location, PERCENTILE_APPROX(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, SUM(budget) AS total_budget, ROUND(AVG(budget), 2) AS avg_budget, COUNT(*) FILTER (WHERE location = 'Bangkok') AS bangkok_rows, STDDEV_SAMP(budget) AS budget_stddev FROM with_last GROUP BY location ORDER BY total_budget DESC
